import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        A = input[ptr]
        ptr += 1
        B = input[ptr]
        ptr += 1

        possible = True
        for i in range(N):
            if A[i] > B[i]:
                possible = False
                break
        if not possible:
            print(-1)
            continue

        groups = defaultdict(list)
        for i in range(N):
            groups[B[i]].append(i)

        operations = []
        used = [False] * N
        for c in sorted(groups.keys()):
            indices = groups[c]
            current = []
            for i in indices:
                if not used[i]:
                    current.append(i)
            if not current:
                continue
            operations.append((c, current))
            for i in current:
                used[i] = True

        for i in range(N):
            if not used[i] and A[i] != B[i]:
                possible = False
                break
        if not possible:
            print(-1)
            continue

        print(len(operations))
        for c, indices in operations:
            print(len(indices), *indices)

solve()
